#include <bits/stdc++.h>
using namespace std;

class Solution { public:
 int maximizeWin(vector<int>& prizePositions,int k){
  int n=prizePositions.size(),l=0,ans=0;vector<int> best(n+1);
  for(int r=0;r<n;++r){while(prizePositions[r]-prizePositions[l]>k)++l;
   int cur=r-l+1;ans=max(ans,cur+best[l]);best[r+1]=max(best[r],cur);
  }return ans;
 }
};
